INSERT INTO site_areas (slug,area_type,country_code,name_ar,name_en,name_fr,currency_code,currency_symbol) VALUES ('colombia','country','CO','كولومبيا','Colombia','Colombie','COP','COP') ON CONFLICT (slug) DO UPDATE SET name_ar=EXCLUDED.name_ar,name_en=EXCLUDED.name_en,currency_code='COP',currency_symbol='COP',is_active=TRUE,updated_at=NOW();
INSERT INTO area_content (area_id,content_key,content_ar,content_en,content_type,section,sort_order) SELECT id,v.k,v.ar,v.en,'text',v.s,v.o FROM site_areas JOIN (VALUES ('seo_title','تحفيظ القرآن وتأسيس العربية أونلاين في كولومبيا | أكاديمية الحافظ','Online Quran and Arabic Foundations in Colombia','seo',0),('seo_description','تحفيظ القرآن الكريم وتأسيس اللغة العربية أونلاين من كولومبيا بحصص فردية وأسعار بالبيزو الكولومبي.','Online Quran memorization and Arabic foundations from Colombia with individual lessons and COP prices.','seo',1),('local_card','Al-Hafiz Academy ofrece clases individuales en línea para memorizar el Corán y aprender los fundamentos del árabe para estudiantes que hablan árabe en Colombia. Bogotá, Medellín, Cali y Barranquilla son referencias geográficas de esta página. Las clases son en línea y la comunicación con la academia se realiza en árabe. La academia no tiene sede, sucursal ni lugar de enseñanza en Colombia.','Online Quran memorization and Arabic foundations for Arabic-speaking learners in Colombia.','local',0)) v(k,ar,en,s,o) ON site_areas.slug='colombia' ON CONFLICT (area_id,content_key) DO UPDATE SET content_ar=EXCLUDED.content_ar,content_en=EXCLUDED.content_en,is_active=TRUE;
INSERT INTO area_packages (area_id,program,package_key,name_ar,name_en,description_ar,price,currency_code,sessions_per_month,is_active,sort_order) SELECT id,v.p,v.k,v.n,v.n,v.d,v.price,'COP',v.sessions,TRUE,v.o FROM site_areas JOIN (VALUES ('quran','quran-4','تحفيظ القرآن — 4 حصص','Quran memorization',49000,'حفظ ومراجعة فردية',4,0),('quran','quran-8','تحفيظ القرآن — 8 حصص','Quran memorization',92000,'حفظ ومراجعة فردية',8,1),('quran','quran-12','تحفيظ القرآن — 12 حصة','Quran memorization',138000,'حفظ ومراجعة فردية',12,2),('quran','quran-16','تحفيظ القرآن — 16 حصة','Quran memorization',181000,'حفظ ومراجعة فردية',16,3),('arabic','arabic-4','تأسيس العربية — 4 حصص','Arabic foundations',65000,'قراءة وفهم',4,0),('arabic','arabic-8','تأسيس العربية — 8 حصص','Arabic foundations',118000,'قراءة وفهم',8,1),('arabic','arabic-12','تأسيس العربية — 12 حصة','Arabic foundations',177000,'قراءة وفهم',12,2),('arabic','arabic-16','تأسيس العربية — 16 حصة','Arabic foundations',236000,'قراءة وفهم',16,3)) v(p,k,n,d,price,desc,sessions,o) ON site_areas.slug='colombia' ON CONFLICT (area_id,package_key) DO UPDATE SET price=EXCLUDED.price,name_ar=EXCLUDED.name_ar,program=EXCLUDED.program,is_active=TRUE;
INSERT INTO area_faq_items (area_id,question_key,question_ar,question_en,answer_ar,answer_en,sort_order) SELECT id,v.k,v.q,v.q,v.a,v.a,v.o FROM site_areas JOIN (VALUES ('co-1','هل الدراسة أونلاين من كولومبيا؟','نعم، الدراسة أونلاين، والمدن المذكورة سياق جغرافي للصفحة فقط دون مقرات أو فروع أو أماكن تدريس محلية.',0),('co-2','هل الأسعار بالبيزو الكولومبي؟','نعم، الأسعار الظاهرة في صفحة كولومبيا بالبيزو الكولومبي.',1),('co-3','بأي لغة يتم التواصل؟','يتم التواصل مع الأكاديمية باللغة العربية.',2),('co-4','هل توجد باقات مخصصة؟','يوجد باقات مخصصة.',3)) v(k,q,a,o) ON site_areas.slug='colombia' ON CONFLICT (area_id,question_key) DO UPDATE SET question_ar=EXCLUDED.question_ar,answer_ar=EXCLUDED.answer_ar,is_active=TRUE;
INSERT INTO area_links (area_id,link_key,label_ar,label_en,href,link_type,is_external,sort_order) SELECT id,v.k,v.l,v.l,v.h,v.t,v.x,v.o FROM site_areas JOIN (VALUES ('canonical','الصفحة الرسمية','https://quran-elhafez.com/colombia','canonical',TRUE,0),('whatsapp','واتساب','https://bit.ly/4aJfOl6','external',TRUE,1),('home','الرئيسية','/','internal',FALSE,2),('games','الألعاب والمسابقات','/games','internal',FALSE,3),('library','المكتبة','/library','internal',FALSE,4)) v(k,l,h,t,x,o) ON site_areas.slug='colombia' ON CONFLICT (area_id,link_key) DO UPDATE SET href=EXCLUDED.href,label_ar=EXCLUDED.label_ar,is_active=TRUE;
INSERT INTO area_themes (area_id,theme_name_ar,theme_name_en,primary_color,secondary_color,accent_color,background_color,text_color) SELECT id,'دفتر أسئلة كولومبيا','Colombia question notebook','#123B8A','#E8F0FF','#F4C542','#F7F9FC','#17213B' FROM site_areas WHERE slug='colombia' ON CONFLICT (area_id) DO UPDATE SET primary_color=EXCLUDED.primary_color,secondary_color=EXCLUDED.secondary_color,accent_color=EXCLUDED.accent_color,background_color=EXCLUDED.background_color,text_color=EXCLUDED.text_color,is_active=TRUE;
INSERT INTO area_cities (area_id,city_key,name_ar,name_en,region_name,sort_order) SELECT id,v.k,v.a,v.e,v.r,v.o FROM site_areas JOIN (VALUES ('bogota','بوغوتا','Bogotá','Bogotá',10),('medellin','ميديلين','Medellín','Antioquia',20),('cali','كالي','Cali','Valle del Cauca',30),('barranquilla','بارانكيا','Barranquilla','Atlántico',40)) v(k,a,e,r,o) ON site_areas.slug='colombia' ON CONFLICT (area_id,city_key) DO UPDATE SET name_ar=EXCLUDED.name_ar,name_en=EXCLUDED.name_en,is_active=TRUE;
INSERT INTO area_timezones (area_id,timezone_name,label_ar,label_en,is_primary,sort_order) SELECT id,'America/Bogota','توقيت كولومبيا (America/Bogota، UTC−05:00)','Colombia Time',TRUE,10 FROM site_areas WHERE slug='colombia' ON CONFLICT (area_id,timezone_name) DO UPDATE SET label_ar=EXCLUDED.label_ar,is_primary=TRUE,is_active=TRUE;
